//! Assembles the source of the generated crate.

use crate::edges::Plan;
use crate::events::render_event_enum;
use crate::render_handlers::render_handlers;
use crate::render_types::render_types;
use crate::tree::Tree;

const HEADER: &str = "\
//! Generated by tools/bm05 (BM-05, spec 10.3). Do not edit.
#![deny(warnings)]

use core::time::Duration;

use estado_core::{Cx, Next};
use estado_macros::machine;

pub const TIMEOUT_SHORT: Duration = Duration::from_millis(250);

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Command {
    Notify(u32),
    Cleanup(u8),
    Alarm,
}

";

/// The `lib.rs` of the generated crate.
pub fn render_machine(tree: &Tree, plan: &Plan) -> String {
    let mut text = String::from(HEADER);
    text.push_str(&render_event_enum());
    text.push_str("\n#[machine(event = Event, effect = Command, ctx = u32)]\npub mod plant {\n    use super::*;\n\n");
    text.push_str(&render_types(tree));
    text.push_str(&render_handlers(tree, plan));
    text.push_str("}\n");
    text
}
